-- FEATURE: BYDAY_ordinal
--------------------------------------------------------------------------------
\echo ''
\echo '--- BYDAY_ordinal ---'
\echo ''

-- DAILY with BYDAY_ordinal should be rejected
SELECT assert_rrule_rejected('reject-daily-byday-ordinal',
    'FREQ=DAILY;BYDAY=2TU;COUNT=5',
    '%BYDAY with ordinal%can only be used with FREQ=MONTHLY or FREQ=YEARLY%');

-- WEEKLY with BYDAY_ordinal should be rejected
SELECT assert_rrule_rejected('reject-weekly-byday-ordinal',
    'FREQ=WEEKLY;BYDAY=2TU;COUNT=5',
    '%BYDAY with ordinal%can only be used with FREQ=MONTHLY or FREQ=YEARLY%');

-- MONTHLY with BYDAY ordinal (2MO/2TU)
SELECT assert_true('matrix-monthly-byday-ordinal',
    (SELECT COUNT(*) >= 1 FROM rrule."all"('FREQ=MONTHLY;BYDAY=2TU;COUNT=5', '2025-01-01 10:00:00'::TIMESTAMP)));

-- YEARLY with BYDAY ordinal (2MO/2TU)
SELECT assert_true('matrix-yearly-byday-ordinal',
    (SELECT COUNT(*) >= 1 FROM rrule."all"('FREQ=YEARLY;BYMONTH=1;BYDAY=2MO;COUNT=5', '2025-01-01 10:00:00'::TIMESTAMP)));

-- HOURLY with BYDAY_ordinal should be rejected
DO $$
DECLARE
    result TIMESTAMP[];
    err_msg TEXT;
BEGIN
    IF (SELECT subday_installed FROM test_config) THEN
        BEGIN
            result := (SELECT array_agg(occurrence ORDER BY occurrence)
                       FROM rrule."all"('FREQ=HOURLY;BYDAY=2TU;COUNT=5', '2025-01-01 10:00:00'::TIMESTAMP) AS occurrence);
            RAISE EXCEPTION 'FAIL [reject-hourly-byday-ordinal]: RRULE was accepted when it should have been rejected';
        EXCEPTION
            WHEN raise_exception THEN
                err_msg := SQLERRM;
                IF err_msg LIKE '%BYDAY with ordinal%can only be used with FREQ=MONTHLY or FREQ=YEARLY%' THEN
                    RAISE NOTICE 'PASS [reject-hourly-byday-ordinal]';
                ELSE
                    RAISE EXCEPTION 'FAIL [reject-hourly-byday-ordinal]: Wrong error. Got: %', err_msg;
                END IF;
        END;
    ELSE
        RAISE NOTICE 'SKIP [reject-hourly-byday-ordinal]: Subday not installed';
    END IF;
END $$;

-- MINUTELY with BYDAY_ordinal should be rejected
DO $$
DECLARE
    result TIMESTAMP[];
