                       FROM rrule."all"('FREQ=MINUTELY;BYDAY=2TU;COUNT=5', '2025-01-01 10:00:00'::TIMESTAMP) AS occurrence);
            RAISE EXCEPTION 'FAIL [reject-minutely-byday-ordinal]: RRULE was accepted when it should have been rejected';
        EXCEPTION
            WHEN raise_exception THEN
