    'FREQ=DAILY;BYWEEKNO=10;COUNT=5',
    '%BYWEEKNO can only be used with FREQ=YEARLY%');

-- WEEKLY with BYWEEKNO should be rejected
SELECT assert_rrule_rejected('reject-weekly-byweekno',
    'FREQ=WEEKLY;BYWEEKNO=10;COUNT=5',
    '%BYWEEKNO can only be used with FREQ=YEARLY%');

-- MONTHLY with BYWEEKNO should be rejected
SELECT assert_rrule_rejected('reject-monthly-byweekno',
    'FREQ=MONTHLY;BYWEEKNO=10;COUNT=5',
    '%BYWEEKNO can only be used with FREQ=YEARLY%');

-- YEARLY with BYWEEKNO=10
SELECT assert_true('matrix-yearly-byweekno',
    (SELECT COUNT(*) >= 1 FROM rrule."all"('FREQ=YEARLY;BYWEEKNO=10;COUNT=5', '2025-01-01 10:00:00'::TIMESTAMP)));

-- HOURLY with BYWEEKNO should be rejected
DO $$
DECLARE
    result TIMESTAMP[];
    err_msg TEXT;
BEGIN
    IF (SELECT subday_installed FROM test_config) THEN
        BEGIN
            result := (SELECT array_agg(occurrence ORDER BY occurrence)
                       FROM rrule."all"('FREQ=HOURLY;BYWEEKNO=10;COUNT=5', '2025-01-01 10:00:00'::TIMESTAMP) AS occurrence);
            RAISE EXCEPTION 'FAIL [reject-hourly-byweekno]: RRULE was accepted when it should have been rejected';
        EXCEPTION
            WHEN raise_exception THEN
                err_msg := SQLERRM;
                IF err_msg LIKE '%BYWEEKNO can only be used with FREQ=YEARLY%' THEN
                    RAISE NOTICE 'PASS [reject-hourly-byweekno]';
                ELSE
                    RAISE EXCEPTION 'FAIL [reject-hourly-byweekno]: Wrong error. Got: %', err_msg;
                END IF;
        END;
    ELSE
        RAISE NOTICE 'SKIP [reject-hourly-byweekno]: Subday not installed';
    END IF;
END $$;

